/**
 * Provisions a brand-new department (organization) in Firestore + Auth.
 *
 * Distinct from setup-demo.ts on purpose: this creates nothing but what a
 * real department needs to get started — the org document, one admin
 * account, and one default (editable) vehicle inspection template so the
 * first officer isn't blocked on an admin building a checklist from
 * scratch. No demo vehicles, no extra users, no synthetic history.
 *
 * Usage:
 *   npm run create-org -- "<Org Name>" <adminEmail>
 *
 * The org id is generated by slugifying the org name (e.g. "Tulsa Example
 * Police Department" -> "tulsa-example-police-department") and checked
 * for collision against Firestore before anything is written. The admin
 * email is checked against Firebase Auth the same way — same
 * verify-before-write discipline as setup-demo.ts's resolveSeedUsers,
 * just checking for *absence* instead of presence: this script refuses
 * to run if the generated org id already exists, or if the email already
 * has an Auth account, rather than silently colliding with either.
 *
 * The admin's Auth account is created here (not looked up — there's
 * nothing to look up yet), so there's no real display name to defer to;
 * first/last name are derived from the email's local part (the same
 * deriveNameFromEmail logic setup-demo.ts uses for the same reason).
 *
 * Prints a password-reset link at the end (via
 * `auth.generatePasswordResetLink`) rather than emailing it — same
 * constraint as inviteOrgUser (functions/src/index.ts): the Admin SDK can
 * generate the link but has no way to send an email itself. Send the
 * printed link to the admin yourself.
 *
 * Prints exactly what it's about to create and requires typing "yes"
 * before writing anything — this creates a real Auth account, not just
 * Firestore documents, so it gets the same confirmation gate as
 * setup-demo.ts's --reset even though nothing here is destructive.
 *
 * Requires a service account key saved at <repo root>/serviceAccountKey.json
 * (Firebase Console -> Project settings -> Service accounts -> Generate new
 * private key). That file is gitignored — never commit it.
 */
import * as fs from "fs";
import * as path from "path";
import * as readline from "readline/promises";
import { initializeApp, cert, type ServiceAccount } from "firebase-admin/app";
import { getAuth, type UserRecord } from "firebase-admin/auth";
import { getFirestore, Timestamp } from "firebase-admin/firestore";
import { v4 as uuidv4 } from "uuid";
import type { TemplateItem } from "../src/types";

const SERVICE_ACCOUNT_PATH = path.resolve(__dirname, "..", "serviceAccountKey.json");

/** Same baseline checklist setup-demo.ts seeds — a sensible, already-reviewed starting point, not a demo-specific one. */
const DEFAULT_TEMPLATE_ITEMS: Array<{ id: string; label: string }> = [
  { id: "tires", label: "Tires" },
  { id: "brakes", label: "Brakes" },
  { id: "lights", label: "Lights" },
  { id: "emergency-light", label: "Emergency Lights" },
  { id: "siren", label: "Siren" },
  { id: "radio", label: "Radio" },
];

function loadServiceAccount(): ServiceAccount {
  if (!fs.existsSync(SERVICE_ACCOUNT_PATH)) {
    console.error(
      `Missing service account key at ${SERVICE_ACCOUNT_PATH}\n\n` +
        "Download one from Firebase Console -> Project settings -> Service accounts\n" +
        "-> Generate new private key, and save it as serviceAccountKey.json in the\n" +
        "project root."
    );
    process.exit(1);
  }
  return JSON.parse(fs.readFileSync(SERVICE_ACCOUNT_PATH, "utf-8"));
}

function getCliArgs(): { orgName: string; adminEmail: string } {
  const args = process.argv.slice(2);
  const [orgName, adminEmail] = args;

  if (!orgName || !adminEmail) {
    console.error(
      'Usage: npm run create-org -- "<Org Name>" <adminEmail>\n\n' +
        "Stands up a brand-new department: generates an org id from the name,\n" +
        "creates the organization document, creates a Firebase Auth account for\n" +
        "the admin (must not already exist), writes their profile (role: admin)\n" +
        "and userOrgs doc, seeds one default vehicle inspection template (active,\n" +
        "fully editable afterward), and prints a password-reset link for the\n" +
        "admin to use.\n\n" +
        "No demo vehicles, users, or extra templates are created — see\n" +
        "setup-demo.ts for that, which is for the demo org specifically.\n\n" +
        "Refuses to run if the generated org id or the admin email already exist."
    );
    process.exit(1);
  }
  return { orgName, adminEmail };
}

/** "Tulsa Example Police Department" -> "tulsa-example-police-department". */
function slugify(name: string): string {
  return name
    .toLowerCase()
    .trim()
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-+|-+$/g, "");
}

/** Turns "j.smith" (from j.smith@department.gov) into "J Smith" — mirrors setup-demo.ts's deriveNameFromEmail (there's no real Auth account to defer to yet, since this script creates it). */
function deriveNameFromEmail(email: string): { firstName: string; lastName: string } {
  const localPart = email.split("@")[0] ?? email;
  const tokens = localPart
    .split(/[._-]+/)
    .filter(Boolean)
    .map((token) => token.charAt(0).toUpperCase() + token.slice(1));

  if (tokens.length === 0) {
    return { firstName: email, lastName: "" };
  }
  if (tokens.length === 1) {
    return { firstName: tokens[0], lastName: "" };
  }
  return { firstName: tokens[0], lastName: tokens.slice(1).join(" ") };
}

/** Prompts on stdin and returns true only if the typed answer is exactly "yes" (case-insensitive). */
async function promptYesNo(question: string): Promise<boolean> {
  const rl = readline.createInterface({ input: process.stdin, output: process.stdout });
  try {
    const answer = await rl.question(question);
    return answer.trim().toLowerCase() === "yes";
  } finally {
    rl.close();
  }
}

async function main() {
  const { orgName, adminEmail } = getCliArgs();
  const trimmedOrgName = orgName.trim();
  const email = adminEmail.trim().toLowerCase();

  if (!trimmedOrgName) {
    console.error("Org name can't be empty.");
    process.exit(1);
  }
  if (!email.includes("@")) {
    console.error(`"${adminEmail}" doesn't look like a valid email address.`);
    process.exit(1);
  }

  const orgId = slugify(trimmedOrgName);
  if (!orgId) {
    console.error(
      `Couldn't generate a valid org id from "${trimmedOrgName}" — try a name with some letters or numbers in it.`
    );
    process.exit(1);
  }

  initializeApp({ credential: cert(loadServiceAccount()) });
  const db = getFirestore();
  const auth = getAuth();

  console.log(`\nGenerated org id: ${orgId}`);
  console.log("\nChecking for collisions before writing anything:");

  // 1. The org id must not already exist.
  const orgRef = db.doc(`organizations/${orgId}`);
  const orgSnap = await orgRef.get();
  if (orgSnap.exists) {
    console.error(
      `\nAborting: organizations/${orgId} already exists (name: "${orgSnap.data()?.name}"). ` +
        "Choose a different org name, or resolve the collision manually. Nothing was written."
    );
    process.exit(1);
  }
  console.log(`  organizations/${orgId}: does not exist — OK`);

  // 2. The admin email must not already have an Auth account.
  let existingAuthUser: UserRecord | undefined;
  try {
    existingAuthUser = await auth.getUserByEmail(email);
  } catch (err) {
    if ((err as { code?: string })?.code !== "auth/user-not-found") {
      console.error(`\nAborting: unexpected error checking Auth for ${email}:`, err);
      process.exit(1);
    }
  }
  if (existingAuthUser) {
    console.error(
      `\nAborting: a Firebase Auth account already exists for ${email} (uid: ${existingAuthUser.uid}). ` +
        "Nothing was written."
    );
    process.exit(1);
  }
  console.log(`  Auth account for ${email}: does not exist — OK`);

  const { firstName, lastName } = deriveNameFromEmail(email);
  const templateId = uuidv4();
  const templateName = "Daily Vehicle Inspection";

  console.log("\nAbout to create:");
  console.log(`  organizations/${orgId}  (name: "${trimmedOrgName}")`);
  console.log(`  Firebase Auth account for ${email}  (display name: "${firstName} ${lastName}")`);
  console.log(`  organizations/${orgId}/users/{new uid}  (role: admin)`);
  console.log(`  userOrgs/{new uid}`);
  console.log(
    `  organizations/${orgId}/inspectionTemplates/${templateId}  ("${templateName}", ` +
      `${DEFAULT_TEMPLATE_ITEMS.length} items, active) — a starting point, fully editable afterward via Admin -> Templates`
  );

  const confirmed = await promptYesNo('\nType "yes" to create this organization, or anything else to cancel: ');
  if (!confirmed) {
    console.log("\nAborted — nothing was created.");
    process.exit(0);
  }

  console.log("\nCreating Firebase Auth account...");
  const userRecord = await auth.createUser({
    email,
    displayName: `${firstName} ${lastName}`,
    emailVerified: false,
  });
  console.log(`  uid: ${userRecord.uid}`);

  console.log("\nWriting Firestore documents...");
  try {
    const now = Timestamp.now();
    const batch = db.batch();

    batch.set(orgRef, {
      name: trimmedOrgName,
      slug: orgId,
      timezone: "America/Chicago",
      plan: "standard",
      settings: { inspectionIntervalDays: 7 },
      isActive: true,
      createdAt: now,
      updatedAt: now,
    });

    batch.set(db.doc(`organizations/${orgId}/users/${userRecord.uid}`), {
      email,
      firstName,
      lastName,
      role: "admin",
      organizationId: orgId,
      isActive: true,
      createdAt: now,
      updatedAt: now,
    });

    batch.set(db.doc(`userOrgs/${userRecord.uid}`), { organizationId: orgId, email });

    const items: TemplateItem[] = DEFAULT_TEMPLATE_ITEMS.map((item, index) => ({
      id: item.id,
      templateId,
      sortOrder: index,
      section: item.label,
      label: item.label,
      responseType: "pass_fail" as const,
      isRequired: true,
      requiresPhoto: false,
      requiresNote: false,
      autoCreateIssueOnFail: true,
    }));
    batch.set(db.doc(`organizations/${orgId}/inspectionTemplates/${templateId}`), {
      organizationId: orgId,
      name: templateName,
      description:
        "Starter checklist created when this department was provisioned — edit or replace it anytime via Admin -> Templates.",
      appliesTo: "vehicle",
      items,
      recurrenceDays: 1,
      version: 1,
      familyId: templateId,
      isActive: true,
      createdAt: now,
      updatedAt: now,
    });

    await batch.commit();
  } catch (err) {
    // Don't leave an orphaned Auth account with no org/profile if the
    // Firestore writes fail after it was already created — same
    // rollback discipline as inviteOrgUser (functions/src/index.ts).
    console.error("\nFirestore writes failed after the Auth account was already created — rolling back:", err);
    await auth.deleteUser(userRecord.uid).catch((cleanupErr) => {
      console.error(
        `Rollback also failed — Auth account ${userRecord.uid} (${email}) is now orphaned. Delete it manually.`,
        cleanupErr
      );
    });
    process.exit(1);
  }
  console.log("  done.");

  console.log("\nGenerating password reset link...");
  let resetLink: string | null = null;
  try {
    resetLink = await auth.generatePasswordResetLink(email);
  } catch (err) {
    console.error(
      `Failed to generate a reset link (the org/admin/template were still created successfully):`,
      err
    );
  }

  console.log("\nDone. Summary:");
  console.log(`  Org id:      ${orgId}`);
  console.log(`  Org name:    ${trimmedOrgName}`);
  console.log(`  Admin email: ${email}`);
  console.log(`  Reset link:  ${resetLink ?? "(failed to generate — have them use \"Forgot password\" on the login page instead)"}`);
  console.log(
    `\nSend the reset link above to ${email} so they can set their own password.\n` +
      `A "${templateName}" template (${DEFAULT_TEMPLATE_ITEMS.length} items) is active and ready to use — ` +
      `it's a starting point, not final: edit or replace it anytime via Admin -> Templates.`
  );
}

main().catch((err) => {
  console.error("create-org failed:", err);
  process.exit(1);
});
